// The Gmail Trigger (simple=false) already returns decoded subject/body plus
// structured address objects (from/to as { value:[{address,name}], text, html }).
// Some sources may instead deliver raw MIME parts under `payload` / a `headers`
// map. Read the structured fields first, then fall back to raw MIME sources.

const raw = $json || {};

const asString = (value) => (typeof value === 'string' ? value : '');

// Resolve an address field to a "Name <addr>" / plain address string.
const addressToString = (field) => {
  if (!field) return '';
  if (typeof field === 'string') return field;
  if (typeof field.text === 'string' && field.text.trim() !== '') return field.text;
  const first = Array.isArray(field.value) ? field.value[0] : null;
  if (first && typeof first.address === 'string') return first.address;
  return '';
};

// Fallback 1: raw MIME headers as array of { name, value } (payload.headers).
const mimeHeaders = Array.isArray(raw.payload?.headers) ? raw.payload.headers : [];
const headerFromMime = (name) => {
  const hit = mimeHeaders.find(
    (h) => String(h?.name || '').toLowerCase() === name.toLowerCase(),
  );
  return asString(hit?.value);
};

// Fallback 2: headers map keyed by lowercase name; values may carry the
// "Header: " prefix, which is stripped here.
const headerMap = raw.headers && !Array.isArray(raw.headers) ? raw.headers : null;
const headerFromMap = (name) => {
  if (!headerMap) return '';
  const value = headerMap[name.toLowerCase()];
  if (typeof value !== 'string') return '';
  const prefix = `${name.toLowerCase()}:`;
  return value.toLowerCase().startsWith(prefix)
    ? value.slice(prefix.length).trim()
    : value.trim();
};

const fromAddress =
  addressToString(raw.from) || headerFromMime('From') || headerFromMap('From');
const toAddress =
  addressToString(raw.to) || headerFromMime('To') || headerFromMap('To');
const subject =
  asString(raw.subject) || headerFromMime('Subject') || headerFromMap('Subject');
const date =
  asString(raw.date) || headerFromMime('Date') || headerFromMap('Date');

// Body: prefer the already-decoded text from the trigger, else base64 MIME parts.
const partData = (part) =>
  part && part.body && typeof part.body.data === 'string' ? part.body.data : '';
const parts = Array.isArray(raw.payload?.parts) ? raw.payload.parts : [];
const textPart = parts.find((p) => p?.mimeType === 'text/plain');
const htmlPart = parts.find((p) => p?.mimeType === 'text/html');

const text = asString(raw.text) || partData(textPart) || partData(raw.payload?.body);
const html = asString(raw.html) || partData(htmlPart);

const labels = Array.isArray(raw.labelIds) ? raw.labelIds : [];

return [
  {
    json: {
      messageId: asString(raw.id) || asString(raw.messageId),
      threadId: asString(raw.threadId),
      from: fromAddress,
      to: toAddress,
      subject,
      date,
      snippet: asString(raw.snippet),
      text,
      html,
      labels,
      raw,
    },
  },
];

const normalized = $('Normalize incoming email').item.json || {};
const routeResponse = $json || {};

const routeOk = routeResponse.ok === true;
const executed = routeResponse.executed === true;

return [{
  json: {
    ok: routeOk,
    executed,
    action: 'receiveAndRoute',
    messageId: normalized.messageId || null,
    threadId: normalized.threadId || null,
    from: normalized.from || '',
    subject: normalized.subject || '',
    routeResponse
  }
}];

const item = $json || {};
const failure = item.error;
let errorMessage;
if (failure && typeof failure === 'object') {
  errorMessage = failure.message || failure.description || failure.name || JSON.stringify(failure);
} else if (typeof failure === 'string' && failure.trim() !== '') {
  errorMessage = failure.trim();
} else if (typeof item.message === 'string' && item.message.trim() !== '') {
  errorMessage = item.message.trim();
} else {
  errorMessage = 'Node failed without error details.';
}

throw new Error(errorMessage);
